"""Verify that a raw result was generated by the checked-out sources."""

import argparse
from pathlib import Path

from cv_mb_qrc.reservoirs.results import verify_result_directory


def main() -> None:
    parser = argparse.ArgumentParser()
    parser.add_argument("path", type=Path)
    args = parser.parse_args()
    report = verify_result_directory(args.path)
    print(f"provenance verified: {report}")


if __name__ == "__main__":
    main()
